  it("redacts secrets from model-facing Linear issue content", async () => {
    const api = gateway({
      ...original,
      title: "Rotate api_key=abcdefghijklmnop",
      description: "Token github_pat_abcdefghijklmnopqrstuvwxyz123456",
    });
    const bound = tools(api);
